 if($attempt && (int)$attempt['attempts']>=10 && strtotime($attempt['last_attempt'])>time()-900)$error='Too many attempts. Try again in 15 minutes.';
 else{$admin=query('SELECT * FROM admins WHERE email=?',[trim((string)($_POST['email']??''))])->fetch();if($admin&&password_verify((string)($_POST['password']??''),$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));query('DELETE FROM login_attempts WHERE ip_hash=?',[$ip]);redirect('admin/index.php');}
 query('INSERT INTO login_attempts(ip_hash,attempts,last_attempt) VALUES(?,1,NOW()) ON DUPLICATE KEY UPDATE attempts=IF(last_attempt < DATE_SUB(NOW(),INTERVAL 15 MINUTE),1,attempts+1),last_attempt=NOW()',[$ip]);$error='Email or password is incorrect.';}}
